.uw-status:not([data-state=operational]):not([data-state=construction]){border-style:dashed}
.uw-card h2{font:700 1.3rem/1.35 Manrope,sans-serif;letter-spacing:-.025em;margin:0 0 8px}
.uw-location{font-size:.8rem;color:var(--s-muted);margin:0 0 16px}
