.uw-pending{font-size:.78rem;color:var(--s-muted);margin:16px 0 0}
.uw-card-actions{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-top:16px}
.uw-details{margin-top:16px;border-top:1px solid var(--s-line);font-size:.8rem;color:var(--s-muted)}
