.uw-source-list a{overflow-wrap:anywhere}
.uw-source-list small{display:block}
.uw-empty,.uw-project-scope{padding:24px;background:var(--s-soft);border-radius:var(--s-radius);font-size:.9rem}
.uw-project-scope{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-top:16px}
